-- v0.22: one knowledge library for Learn (articles, videos, books, quizzes); quotes stay in the app and are searchable.
-- The library table is rebuilt to allow quizzes and to hold full article text, topics, a pin for the top 5, and quiz settings.

CREATE TABLE library_new (
  id            TEXT PRIMARY KEY,
  kind          TEXT NOT NULL CHECK (kind IN ('article', 'book', 'video', 'quiz')),
  title         TEXT NOT NULL,
  author        TEXT NOT NULL DEFAULT '',
  url           TEXT NOT NULL DEFAULT '',     -- article or video link; for a book, where to buy it
  summary       TEXT NOT NULL DEFAULT '',     -- a short summary in our own words
  body          TEXT NOT NULL DEFAULT '',     -- full article text (simple formatting: ## headings, - lists, **bold**, [links](https://…))
  image         TEXT NOT NULL DEFAULT '',
  icon          TEXT NOT NULL DEFAULT '',     -- one emoji for articles and quizzes
  isbn          TEXT NOT NULL DEFAULT '',
  chapters      INTEGER NOT NULL DEFAULT 0,
  minutes       INTEGER NOT NULL DEFAULT 0,
  topics        TEXT NOT NULL DEFAULT '',     -- comma-separated topic ids (see TOPICS in api/src/index.js)
  pinned        INTEGER NOT NULL DEFAULT 0,   -- 1 = always in the top 5 of its type
  quiz          TEXT NOT NULL DEFAULT '',     -- quizzes: JSON {questions:[{q, options[2-4], answer, explain, source}], related:[ids], reviewNote}
  pass_mark     INTEGER NOT NULL DEFAULT 8,   -- quizzes: correct answers needed to pass
  retry_minutes INTEGER NOT NULL DEFAULT 10,  -- quizzes: wait before trying again
  status        TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'approved')),
  priority      INTEGER NOT NULL DEFAULT 100,
  created_by    TEXT,
  created_at    INTEGER NOT NULL,
  updated_at    INTEGER NOT NULL
);
INSERT INTO library_new (id, kind, title, author, url, summary, image, isbn, chapters, minutes, status, priority, created_by, created_at, updated_at)
  SELECT id, kind, title, author, url, summary, image, isbn, chapters, minutes, status, priority, created_by, created_at, updated_at FROM library;
DROP TABLE library;
ALTER TABLE library_new RENAME TO library;
CREATE INDEX IF NOT EXISTS idx_library_list ON library(status, kind, priority);
UPDATE library SET topics = 'masters' WHERE kind = 'book' AND topics = '';
UPDATE library SET topics = 'masters' WHERE kind = 'video' AND topics = '';

-- Anonymous counts only: how often items are opened, finished, and quizzes passed. No people, no devices, no IP addresses.
CREATE TABLE IF NOT EXISTS library_stats (
  item_id TEXT NOT NULL,
  action  TEXT NOT NULL CHECK (action IN ('open', 'done', 'pass')),
  day     TEXT NOT NULL,                 -- YYYY-MM-DD (center time)
  n       INTEGER NOT NULL DEFAULT 0,
  PRIMARY KEY (item_id, action, day)
);

-- Quiz challenge (admins can edit, reorder or pause it)
INSERT OR IGNORE INTO challenges (id, title, description, kind, days, minutes, target, material, cadence, per_period, item_points, audience, points, priority, signup, active, created_at, updated_at) VALUES
 ('e-quiz5', 'Pass 5 quizzes · 60 days', 'Check your understanding: pass 5 quizzes in Learn within 60 days. Catching up is fine.',
   'education', 60, 0, 5, 'quiz', 'week', 1, 0, 'all', 50, 80, 0, 1, strftime('%s','now') * 1000, strftime('%s','now') * 1000);

-- Learn articles that used to be built into Copilot (same ids, so people keep their ✓), and the draft quizzes
INSERT OR IGNORE INTO library (id, kind, title, author, url, summary, body, icon, topics, pinned, status, priority, created_at, updated_at) VALUES ('learn-to-meditate', 'article', 'Learn to Meditate', 'Science of Spirituality', '', 'How to begin a simple daily sitting, and where to get free meditation instruction from Science of Spirituality.', 'Meditation is the practice of turning our attention inward and letting the mind become still. You do not need special equipment or experience; you need a little time, a quiet place, and a sincere wish to begin.

- Choose a regular time when you are least likely to be disturbed, such as early morning.
- Sit in any position that is comfortable for you: on a chair, a cushion, or the floor.
- Keep the body relaxed and still, and gently close your eyes.
- Let your attention rest inward. When thoughts come, do not fight them; simply and gently return your attention.
- Start with a length you can keep up every day, then let it grow naturally.

The best way to learn is with proper guidance. Science of Spirituality offers free meditation instruction online and at its centers, including the Learn to Meditate series.

**Read more**
- [Learn Meditation on sos.org](https://sos.org/meditation/learn-meditation/)
- [Learn to Meditate online series](https://sos.org/webinars/learn-to-meditate-series/)', '🧘', 'basics', 1, 'approved', 10, strftime('%s','now') * 1000, strftime('%s','now') * 1000);
INSERT OR IGNORE INTO library (id, kind, title, author, url, summary, body, icon, topics, pinned, status, priority, created_at, updated_at) VALUES ('improve-meditation', 'article', 'Tips on Improving Meditation', 'Science of Spirituality', '', 'Practical habits that help many meditators sit longer, more regularly and more deeply.', 'Small, steady changes often make the biggest difference over time.

- Sit at the same time and in the same place each day; regularity builds momentum.
- Meditate before a heavy meal rather than right after one.
- Keep the body completely still. A still body helps the mind settle.
- Treat a wandering mind as part of the practice, not a failure. Each gentle return counts.
- Let go of expectations. Simply give each sitting your full, loving attention.
- After each sitting, note a reflection in the Timer. Patterns become clearer over weeks.
- Increase your time gradually, a few minutes at a time.

If questions come up in your practice, the Meditation FAQs on sos.org, or a local Science of Spirituality center, can help.

**Read more**
- [Meditation FAQs on sos.org](https://sos.org/meditation/meditation-faq/)', '🌱', 'basics', 1, 'approved', 20, strftime('%s','now') * 1000, strftime('%s','now') * 1000);
INSERT OR IGNORE INTO library (id, kind, title, author, url, summary, body, icon, topics, pinned, status, priority, created_at, updated_at) VALUES ('benefits', 'article', 'Benefits of Meditation', 'Science of Spirituality', '', 'Why people meditate: a calmer mind, steadier focus, and a deeper sense of peace and purpose.', 'People who meditate regularly often describe a calmer, clearer mind and a greater ability to respond to life’s ups and downs with patience. Many find that their focus, relationships and sense of well-being improve over time.

Research on meditation has reported benefits such as reduced stress for many people. Meditation is not a substitute for medical or mental health care; please talk with a health professional about any health concern.

Beyond these everyday benefits, Science of Spirituality presents meditation as a path to spiritual growth and inner peace. Read more on sos.org.

**Read more**
- [Benefits of Meditation on sos.org](https://sos.org/benefits-from-meditation/)', '✨', 'health', 1, 'approved', 30, strftime('%s','now') * 1000, strftime('%s','now') * 1000);
INSERT OR IGNORE INTO library (id, kind, title, author, url, summary, body, icon, topics, pinned, status, priority, created_at, updated_at) VALUES ('know-the-masters', 'article', 'Know the Masters', 'Science of Spirituality', 'https://sos.org/sant-rajinder-singh/', 'Learn about Sant Rajinder Singh Ji Maharaj, spiritual head of Science of Spirituality, and the role of a spiritual Master.', '', '🙏', 'masters', 1, 'approved', 40, strftime('%s','now') * 1000, strftime('%s','now') * 1000);
INSERT OR IGNORE INTO library (id, kind, title, author, url, summary, body, icon, topics, pinned, status, priority, created_at, updated_at) VALUES ('spiritual-goals', 'article', 'Spiritual Goals', 'Science of Spirituality', 'https://sos.org/spirituality/finding-your-true-purpose/', 'Explore the purpose of life and the spiritual goals that meditation helps us move toward.', '', '🎯', 'science', 1, 'approved', 50, strftime('%s','now') * 1000, strftime('%s','now') * 1000);
INSERT OR IGNORE INTO library (id, kind, title, author, url, summary, body, icon, topics, pinned, status, priority, created_at, updated_at) VALUES ('spiritual-teachings', 'article', 'Spiritual Teachings', 'Science of Spirituality', 'https://sos.org/spirituality/spiritual-growth/', 'The teachings of Science of Spirituality on spiritual growth, awareness and living an ethical life.', '', '📖', 'science', 1, 'approved', 60, strftime('%s','now') * 1000, strftime('%s','now') * 1000);
INSERT OR IGNORE INTO library (id, kind, title, author, url, summary, body, icon, topics, pinned, status, priority, created_at, updated_at) VALUES ('wandering-mind', 'article', 'When the Mind Wanders', 'Science of Spirituality', '', 'Thoughts are natural. How to meet a busy mind with patience instead of frustration.', 'Almost everyone finds the mind wandering, especially at first. This is not a sign that meditation is “not working.”

When you notice you have drifted into thought, that moment of noticing is itself a success. Without judging yourself, gently bring your attention back. Over weeks and months these returns become quicker and the periods of stillness longer.

It can help to sit at a time when the mind is naturally quieter, such as early morning, and to avoid stimulating activities right before you sit.

**Read more**
- [Meditation FAQs on sos.org](https://sos.org/meditation/meditation-faq/)', '🌀', 'basics', 0, 'approved', 70, strftime('%s','now') * 1000, strftime('%s','now') * 1000);
INSERT OR IGNORE INTO library (id, kind, title, author, url, summary, body, icon, topics, pinned, status, priority, created_at, updated_at) VALUES ('daily-habit', 'article', 'Building a Daily Practice', 'Science of Spirituality', '', 'Consistency matters more than length. How to make meditation part of every day.', 'A shorter sitting done every day usually helps more than a long sitting done now and then.

- Pick a daily target you can keep, and set it on the Today screen.
- Link meditation to something you already do, such as waking up.
- Use the Timer so you are not watching the clock.
- Watch your streak and consistency in Insights, but be gentle with yourself on a missed day. Simply begin again.', '📅', 'basics', 0, 'approved', 80, strftime('%s','now') * 1000, strftime('%s','now') * 1000);
INSERT OR IGNORE INTO library (id, kind, title, author, url, summary, body, icon, topics, pinned, status, priority, created_at, updated_at) VALUES ('meditation-space', 'article', 'Creating a Space to Meditate', 'Science of Spirituality', '', 'A quiet, simple corner can make it easier to settle in each day.', 'Any quiet spot will do. What helps most is that it is comfortable, reasonably quiet, and used regularly.

- Choose a place where you are unlikely to be interrupted.
- Keep a comfortable cushion or chair there.
- Put your phone on silent (the Timer keeps the screen on so the end bell can play).
- A light blanket can keep you warm during longer sittings.', '🕯️', 'basics', 0, 'approved', 90, strftime('%s','now') * 1000, strftime('%s','now') * 1000);
INSERT OR IGNORE INTO library (id, kind, title, author, url, summary, body, icon, topics, pinned, status, priority, created_at, updated_at) VALUES ('find-center', 'article', 'Find a Center or Program', 'Science of Spirituality', 'https://sos.org/find-center/', 'Meditate with others at a local Science of Spirituality center or join a program online.', '', '📍', 'satsang', 0, 'approved', 100, strftime('%s','now') * 1000, strftime('%s','now') * 1000);
INSERT OR IGNORE INTO library (id, kind, title, author, url, summary, body, icon, topics, pinned, status, priority, created_at, updated_at) VALUES ('meditation-faq', 'article', 'Meditation FAQs', 'Science of Spirituality', 'https://sos.org/meditation/meditation-faq/', 'Answers to common questions about meditation from Science of Spirituality.', '', '❓', 'basics', 0, 'approved', 110, strftime('%s','now') * 1000, strftime('%s','now') * 1000);
INSERT OR IGNORE INTO library (id, kind, title, author, url, summary, body, icon, topics, pinned, status, priority, created_at, updated_at) VALUES ('spiritual-quotes', 'article', 'Spiritual Quotes', 'Science of Spirituality', 'https://sos.org/spiritual-quotes/', 'Inspiring quotes from Sant Rajinder Singh Ji Maharaj on sos.org.', '', '💬', 'masters', 0, 'approved', 120, strftime('%s','now') * 1000, strftime('%s','now') * 1000);
INSERT OR IGNORE INTO library (id, kind, title, author, summary, icon, topics, quiz, pass_mark, retry_minutes, status, priority, created_at, updated_at) VALUES ('q-benefits', 'quiz', 'Benefits of Meditation', 'Draft for review', 'What regular meditation does for body, mind, emotions and spirit.', '🧩', 'health,basics', '{"questions":[{"q":"According to Science of Spirituality, what is the real reason to meditate?","options":["To lower blood pressure","To become aware of our spiritual nature","To sleep better","To improve productivity at work"],"answer":1,"explain":"sos.org calls awareness of our spiritual nature the real reason to meditate; the benefits to body, mind and emotions are by-products.","source":"sos.org/benefits-from-meditation"},{"q":"Can regular, accurate time in meditation help reduce stress and anxiety?","options":["Yes","No"],"answer":0,"explain":"sos.org states that spending regular, accurate time in meditation can reduce stress and anxiety.","source":"sos.org/benefits-from-meditation"},{"q":"Which of these is described as a physical benefit of meditation?","options":["Greater resistance to disease and better recovery","Needing no sleep at all","Never feeling pain again","Weight loss without effort"],"answer":0,"explain":"Meditation is said to increase resistance to disease and help recovery after surgery and illness.","source":"sos.org/benefits-from-meditation"},{"q":"How do brain waves typically change during meditation, according to sos.org?","options":["They speed up to 30 Hz or more","They slow down (about 5–8 Hz), a state of deep relaxation","They stop completely","They don''t change"],"answer":1,"explain":"sos.org contrasts about 13–20 Hz during stressful activity with about 5–8 Hz during meditation.","source":"sos.org/benefits-from-meditation"},{"q":"Which mental benefit comes from reduced stress?","options":["Greater clarity, focus and productivity","Forgetting everything","Needing more stimulation","Becoming less patient"],"answer":0,"explain":"Less stress brings greater mental clarity, better focus and higher productivity.","source":"sos.org/benefits-from-meditation"},{"q":"How can meditation help our relationships?","options":["It makes us avoid people","It fosters tolerance, respect, humility and kindness","It makes us win more arguments","It has no effect on relationships"],"answer":1,"explain":"Meditation is said to foster tolerance, respect, humility, kindness and better communication.","source":"sos.org/benefits-from-meditation"},{"q":"Is meditation presented as a replacement for medical or mental-health care?","options":["Yes","No"],"answer":1,"explain":"It is presented as a supplement, not a replacement. Please see a health professional for any health concern.","source":"sos.org/benefits-from-meditation; Copilot Learn: Benefits of Meditation"},{"q":"What does sos.org say about meditation and rest?","options":["It is less restful than sleep","It can give more rest than the same amount of sleep","It replaces sleep entirely","It makes us restless"],"answer":1,"explain":"Body and mind are still, with no dreams triggering reactions, so meditation can be more restful than the same time asleep.","source":"sos.org/benefits-from-meditation"},{"q":"How does inner peace from meditation affect the world around us?","options":["It stays private and has no effect","It radiates outward and contributes to outer peace","It makes us withdraw from the world","It only helps on weekends"],"answer":1,"explain":"Inner peace gained in meditation radiates outward and contributes to peace in the world.","source":"sos.org/benefits-from-meditation"},{"q":"What does regular practice give us in tense moments?","options":["A calm ''inner retreat'' we can turn to","A reason to react quickly","Nothing until we retire","Louder thoughts"],"answer":0,"explain":"Practising regularly makes it easier to pause and find calm during tense moments.","source":"sos.org/benefits-from-meditation"}],"related":["benefits"],"reviewNote":""}', 8, 10, 'draft', 10, strftime('%s','now') * 1000, strftime('%s','now') * 1000);
INSERT OR IGNORE INTO library (id, kind, title, author, summary, icon, topics, quiz, pass_mark, retry_minutes, status, priority, created_at, updated_at) VALUES ('q-science', 'quiz', 'Why Meditation Is a Science', 'Draft for review', 'Why Science of Spirituality calls meditation an experiment anyone can do.', '🧩', 'science', '{"questions":[{"q":"Where does Science of Spirituality say the experiment of meditation is carried out?","options":["In a university laboratory","In the laboratory of our own body","Only in a temple","Only in nature"],"answer":1,"explain":"Spirituality is presented as a science we can all conduct in the laboratory of our own bodies.","source":"Sant Rajinder Singh Ji Maharaj, interview (Khaleej Times, 2024)"},{"q":"In a scientific approach to spirituality, how should we treat spiritual teachings?","options":["Accept them without question","As hypotheses to test for ourselves","As stories only","As rules for other people"],"answer":1,"explain":"Sant Rajinder Singh Ji encourages seekers to grasp the principles and test the hypotheses for themselves.","source":"Sant Rajinder Singh Ji Maharaj, interview (Life Positive)"},{"q":"Sant Rajinder Singh Ji''s background before his spiritual mission was in…","options":["Medicine","Law","Science, computers and telecommunications","Agriculture"],"answer":2,"explain":"He worked in science, computers and telecommunications before his mission began in 1989.","source":"sos.org/sant-rajinder-singh-ji-maharaj"},{"q":"How does Sant Rajinder Singh Ji describe science and spirituality?","options":["As enemies","As two sides of the same coin","As unrelated","As the same thing"],"answer":1,"explain":"He has said science and spirituality are two sides of the same coin, both seeking answers to life''s big questions.","source":"Sant Rajinder Singh Ji Maharaj, interview (Life Positive)"},{"q":"Like any good experiment, meditation works best when it is…","options":["Done once in a while","Done regularly, with accurate time","Rushed","Done only in a group"],"answer":1,"explain":"Regular, accurate time in meditation is the key to results.","source":"sos.org/benefits-from-meditation; sos.org/meditation/meditation-faq"},{"q":"In meditation, where is the attention withdrawn and focused?","options":["On the breath at the nose","At a point between and behind the eyebrows","On the heart","On the feet"],"answer":1,"explain":"Attention is withdrawn from the world and the body and concentrated at a point between and behind the eyebrows.","source":"Sant Rajinder Singh Ji Maharaj, ''Meditation and higher consciousness'' (Daily Pioneer, 2017)"},{"q":"According to the teachings, the experience of meditation is something we must…","options":["Take only on faith","Verify through our own experience","Read about in books only","Leave to experts"],"answer":1,"explain":"The approach is experiential: each person can experience the inner Light and Sound for themselves.","source":"Wikipedia: Science of Spirituality (summarising sos.org)"},{"q":"Does following this science require leaving your family, job or religion?","options":["Yes","No"],"answer":1,"explain":"sos.org says spirituality does not require leaving one''s family, job, home or religion.","source":"sos.org/spirituality/spiritual-master"},{"q":"What has modern research on meditation reported, as cited by sos.org?","options":["No effects at all","It may ease anxiety, depression and pain","It cures every disease","It only works for monks"],"answer":1,"explain":"A Johns Hopkins review of well-designed trials, cited on sos.org, reported that meditation may ease anxiety, depression and pain.","source":"sos.org/benefits-from-meditation (JAMA Internal Medicine review)"},{"q":"The name ''Science of Spirituality'' suggests that spirituality is…","options":["Unknowable","A practical, testable path","Only about rituals","Only for scientists"],"answer":1,"explain":"The organization presents meditation as a practical method anyone can try and verify.","source":"sos.org/about-us"}],"related":["spiritual-teachings"],"reviewNote":""}', 8, 10, 'draft', 20, strftime('%s','now') * 1000, strftime('%s','now') * 1000);
INSERT OR IGNORE INTO library (id, kind, title, author, summary, icon, topics, quiz, pass_mark, retry_minutes, status, priority, created_at, updated_at) VALUES ('q-tips', 'quiz', 'Tips for Better Meditation', 'Draft for review', 'Practical habits that help you sit longer, more regularly and more deeply.', '🧩', 'basics', '{"questions":[{"q":"How should you choose a meditation posture?","options":["The most difficult one","One where you can sit comfortably without falling asleep or moving","Always lying down","Standing up"],"answer":1,"explain":"sos.org: find a pose in which you can sit comfortably without falling asleep or moving.","source":"sos.org/meditation/meditation-faq"},{"q":"When is the best time to meditate?","options":["Whenever you are tired","A time when you are wide awake and won''t be interrupted, every day","Right after a heavy meal","Only on weekends"],"answer":1,"explain":"Pick a time when you are alert and can focus without interruption, and keep to it daily.","source":"sos.org/meditation/meditation-faq"},{"q":"How long might a beginner start with?","options":["5 to 10 minutes a day, building toward 30 minutes or more","3 hours a day","1 minute a week","Only as long as a song"],"answer":0,"explain":"Beginners can start with 5–10 minutes and build toward about 30 minutes or more.","source":"sos.org/meditation/meditation-faq"},{"q":"What does the SOS technique use to help still the mind?","options":["Loud music","The mental repetition of a calming word","Counting money","Watching a video"],"answer":1,"explain":"SOS Meditation uses the mental repetition of a calming word.","source":"sos.org/meditation/meditation-faq"},{"q":"Should you try to forcefully control your thoughts?","options":["Yes","No"],"answer":1,"explain":"Don''t fight the mind; gently aim to still it. Meditation is about stilling the mind.","source":"sos.org/meditation/meditation-faq"},{"q":"Meditating at the same time each day is compared to…","options":["Brushing your teeth morning and night","Running a marathon","Going on vacation","Paying taxes"],"answer":0,"explain":"A regular time builds the habit, just like brushing your teeth.","source":"sos.org/meditation/meditation-faq"},{"q":"How can a quiet spot at home help?","options":["It reminds you to meditate when you see it","It isn''t helpful","It makes meditation harder","It''s only for experts"],"answer":0,"explain":"A set-aside spot reminds you to sit.","source":"sos.org/meditation/meditation-faq"},{"q":"What helps strengthen focus for meditation during the day?","options":["Multitasking as much as possible","Doing one thing at a time","Checking the phone often","Skipping meals"],"answer":1,"explain":"Practising doing one thing at a time during the day strengthens focus.","source":"sos.org/meditation/meditation-faq"},{"q":"Why keep a journal of your meditation?","options":["To track time, experiences, difficulties and milestones and stay motivated","To show others","It isn''t recommended","To replace meditation"],"answer":0,"explain":"A journal of practice time, experiences, difficulties and milestones helps you stay motivated.","source":"sos.org/meditation/meditation-faq"},{"q":"Meditating with love in the heart makes stilling the mind…","options":["Harder","Easier","Impossible","Irrelevant"],"answer":1,"explain":"sos.org says meditating with love in your heart makes stilling the mind easier.","source":"sos.org/meditation/meditation-faq"}],"related":["improve-meditation","daily-habit","wandering-mind","meditation-space"],"reviewNote":""}', 8, 10, 'draft', 30, strftime('%s','now') * 1000, strftime('%s','now') * 1000);
INSERT OR IGNORE INTO library (id, kind, title, author, summary, icon, topics, quiz, pass_mark, retry_minutes, status, priority, created_at, updated_at) VALUES ('q-santji', 'quiz', 'How Well Do You Know Sant Rajinder Singh Ji Maharaj?', 'Draft for review', 'The life and work of the spiritual head of Science of Spirituality.', '🧩', 'masters', '{"questions":[{"q":"In which year was Sant Rajinder Singh Ji Maharaj born?","options":["1921","1946","1958","1966"],"answer":1,"explain":"He was born on 20 September 1946 in India.","source":"sos.org/sant-rajinder-singh-ji-maharaj"},{"q":"Where did he earn his engineering degree in India?","options":["IIT Madras","IIT Bombay","Delhi University","IIT Kanpur"],"answer":0,"explain":"B.Tech in Electrical Engineering from IIT Madras (1967); M.S. from the Illinois Institute of Technology, Chicago (1970).","source":"sos.org/sant-rajinder-singh-ji-maharaj"},{"q":"When did his spiritual mission begin?","options":["1974","1989","1999","2005"],"answer":1,"explain":"His mission began in 1989 at the direction of Sant Darshan Singh Ji Maharaj.","source":"sos.org/sant-rajinder-singh-ji-maharaj"},{"q":"Under which two Masters did he train?","options":["Sant Kirpal Singh Ji and Sant Darshan Singh Ji","Only Sant Kirpal Singh Ji","Only Sant Darshan Singh Ji","None"],"answer":0,"explain":"He trained under Sant Kirpal Singh Ji Maharaj (1894–1974) and Sant Darshan Singh Ji Maharaj (1921–1989).","source":"sos.org/sant-rajinder-singh-ji-maharaj"},{"q":"Which of these is a book by Sant Rajinder Singh Ji Maharaj?","options":["Detox the Mind","The Power of Now","Be Here Now","The Alchemist"],"answer":0,"explain":"His books include Detox the Mind, Meditation as Medication for the Soul, Inner and Outer Peace through Meditation and Empowering Your Soul through Meditation.","source":"sos.org/sant-rajinder-singh-ji-maharaj"},{"q":"Into how many languages have his books been translated, according to sos.org?","options":["About 5","About 15","56","Over 200"],"answer":2,"explain":"sos.org says his books have been translated into 56 languages.","source":"sos.org/sant-rajinder-singh-ji-maharaj"},{"q":"Which festival did he inspire that draws over 50,000 people a year?","options":["Veggie Fest","Peace Fest Minneapolis","Diwali Mela","Yoga Day"],"answer":0,"explain":"Veggie Fest began in 2005 and is one of North America''s largest vegetarian food and wellness festivals.","source":"sos.org/sant-rajinder-singh-ji-maharaj"},{"q":"Which schools does his Darshan Education Foundation run?","options":["Darshan Academy schools","Kirpal Colleges","Peace Universities","None"],"answer":0,"explain":"He is Founder and Chairman of the Darshan Education Foundation, which runs Darshan Academy schools.","source":"sos.org/sant-rajinder-singh-ji-maharaj"},{"q":"Which two international conferences are associated with him in Delhi?","options":["Human Unity Conference and Global Conference on Mysticism","World Economic Forum and G20","Olympics and Asian Games","None"],"answer":0,"explain":"The International Human Unity Conference and the Global Conference on Mysticism.","source":"sos.org/sant-rajinder-singh-ji-maharaj"},{"q":"How many Science of Spirituality centers are there worldwide, according to sos.org?","options":["About 35","About 350","Over 3,500","Over 35,000"],"answer":2,"explain":"sos.org says SOS has over 3,500 centers (in 50 countries).","source":"sos.org/about-us; sos.org/sant-rajinder-singh-ji-maharaj"}],"related":["know-the-masters"],"reviewNote":""}', 8, 10, 'draft', 40, strftime('%s','now') * 1000, strftime('%s','now') * 1000);
INSERT OR IGNORE INTO library (id, kind, title, author, summary, icon, topics, quiz, pass_mark, retry_minutes, status, priority, created_at, updated_at) VALUES ('q-satsang', 'quiz', 'Benefits of Attending Weekly Satsang', 'Draft for review', 'Why the weekly gathering for spiritual talk and group meditation helps our practice.', '🧩', 'satsang', '{"questions":[{"q":"What does the word ''satsang'' mean?","options":["Company of truth","A festival","A meal","A holiday"],"answer":0,"explain":"Satsang means the company of truth: gathering to hear about spirituality and to meditate together.","source":"General meaning of the term (please review)"},{"q":"What usually happens at a satsang at our center?","options":["A spiritual talk and group meditation","Only social chatting","A sales presentation","Exercise classes"],"answer":0,"explain":"Satsang brings a spiritual talk and a meditation sitting together.","source":"Minneapolis center programs (please review)"},{"q":"How can regular satsang help our daily meditation?","options":["It reminds and inspires us to keep practising","It replaces daily meditation","It makes meditation unnecessary","It has no effect"],"answer":0,"explain":"Satsang renews our inspiration and reminds us of the goal, which supports daily practice.","source":"Teachings on satsang (please review)"},{"q":"Is satsang meant to replace your own daily meditation?","options":["Yes","No"],"answer":1,"explain":"Satsang supports daily practice; it does not replace it.","source":"Teachings on satsang (please review)"},{"q":"Why can meditating in a group feel easier?","options":["The uplifting, peaceful atmosphere helps us sit still","Someone keeps score","It is shorter","There is no reason"],"answer":0,"explain":"Many find the shared, peaceful atmosphere helps them settle and sit longer.","source":"Center experience (please review)"},{"q":"Where can questions about the practice be answered?","options":["At satsang and with center volunteers","Nowhere","Only online forums","Only in books"],"answer":0,"explain":"Satsang and center volunteers are good places to ask questions about the practice.","source":"Minneapolis center (please review)"},{"q":"Do Science of Spirituality programs, including satsang, cost anything?","options":["Yes, a small fee","No, they are free","Only for members","Only on weekends"],"answer":1,"explain":"All SOS programs are free and open to all; the organization is run by volunteers.","source":"sos.org/about-us"},{"q":"Besides learning, what does satsang offer?","options":["A sense of community and belonging","Competition","Nothing else","Networking for business"],"answer":0,"explain":"Satsang connects us with others on the same path.","source":"Center experience (please review)"},{"q":"Can listening to talks by the Master help our spiritual understanding?","options":["Yes","No"],"answer":0,"explain":"Sant Rajinder Singh Ji Maharaj''s talks explain the teachings and give practical guidance for meditation.","source":"sos.org/spirituality/spiritual-master"},{"q":"What is a helpful attitude when attending satsang?","options":["Receptive, with attention on the talk and meditation","Checking the phone","Planning the week","Talking with neighbours during meditation"],"answer":0,"explain":"Coming with a receptive, attentive mind helps us benefit most.","source":"Center guidelines (please review)"}],"related":["spiritual-teachings"],"reviewNote":"No dedicated satsang page was found on sos.org; please check these against the teachings before approving."}', 8, 10, 'draft', 50, strftime('%s','now') * 1000, strftime('%s','now') * 1000);
INSERT OR IGNORE INTO library (id, kind, title, author, summary, icon, topics, quiz, pass_mark, retry_minutes, status, priority, created_at, updated_at) VALUES ('q-light-sound', 'quiz', 'The Inner Light and Sound', 'Draft for review', 'The basics of meditation on the inner Light and Sound as taught by Science of Spirituality.', '🧩', 'science,basics', '{"questions":[{"q":"What do the Masters of Science of Spirituality teach reverberates in all creation?","options":["A divine current of Light and Sound","Electricity","Silence only","Nothing"],"answer":0,"explain":"The teaching is that a divine current of Light and Sound reverberates in all creation.","source":"Wikipedia: Rajinder Singh (summarising SOS teachings)"},{"q":"Meditation is a process by which we come in contact with the Light and Sound that is…","options":["Already within us","Only in holy places","Only in nature","Created by the meditator"],"answer":0,"explain":"Meditation brings us in contact with the Light and Sound of God already within ourselves.","source":"Wikipedia: Rajinder Singh (summarising SOS teachings)"},{"q":"Where is attention concentrated in this meditation?","options":["Between and behind the eyebrows","At the navel","At the tip of the nose","On the heart"],"answer":0,"explain":"We withdraw attention from the world and body and concentrate it at a point between and behind the eyebrows.","source":"Sant Rajinder Singh Ji Maharaj, Daily Pioneer (2017)"},{"q":"What is that point sometimes called?","options":["The seat of the soul","The third chakra","The solar plexus","The crown"],"answer":0,"explain":"When attention is withdrawn there, the soul is at the seat of the soul and can travel on the Light and Sound.","source":"Sant Rajinder Singh Ji Maharaj, Daily Pioneer (2017)"},{"q":"According to the teachings, who opens our ''spiritual eye''?","options":["The attention of a spiritual Master","A doctor","Reading many books","Nobody can"],"answer":0,"explain":"sos.org: it is the attention of a spiritual Master that can open our spiritual eye.","source":"sos.org/spirituality/spiritual-master"},{"q":"Where does the current of Light and Sound lead the soul?","options":["Back to its source","Into more worldly activity","Nowhere","To sleep"],"answer":0,"explain":"The soul can travel on the Light and Sound through the higher planes back to its source.","source":"Sant Rajinder Singh Ji Maharaj, Daily Pioneer (2017)"},{"q":"Does this meditation require special clothes or postures?","options":["Yes","No"],"answer":1,"explain":"No special clothes or postures: sit comfortably and still.","source":"SOS program descriptions; sos.org/meditation/meditation-faq"},{"q":"What helps the attention collect at the seat of the soul?","options":["Keeping the body still and repeating a calming word","Moving often","Opening the eyes wide","Thinking about the day"],"answer":0,"explain":"A still body and the mental repetition of a calming word help the attention collect.","source":"sos.org/meditation/meditation-faq"},{"q":"Do the Masters describe the inner Light and Sound as belonging to one religion only?","options":["Yes","No"],"answer":1,"explain":"The teachings recognise the oneness at the heart of all religions; one does not have to leave one''s religion.","source":"sos.org/spirituality/spiritual-master"},{"q":"What is said about inner experiences and fear of death?","options":["They can reduce fear and bring peace","They increase fear","They have nothing to do with it","They are only imagination"],"answer":0,"explain":"sos.org says meditative experiences confirm the soul continues after death, reducing fear.","source":"sos.org/benefits-from-meditation"}],"related":["spiritual-teachings","learn-to-meditate"],"reviewNote":""}', 8, 10, 'draft', 60, strftime('%s','now') * 1000, strftime('%s','now') * 1000);
INSERT OR IGNORE INTO library (id, kind, title, author, summary, icon, topics, quiz, pass_mark, retry_minutes, status, priority, created_at, updated_at) VALUES ('q-masters', 'quiz', 'The Masters of Science of Spirituality', 'Draft for review', 'The lineage of Masters: Sant Kirpal Singh Ji, Sant Darshan Singh Ji and Sant Rajinder Singh Ji.', '🧩', 'masters', '{"questions":[{"q":"What are the years of Sant Kirpal Singh Ji Maharaj?","options":["1894–1974","1921–1989","1858–1948","1946–present"],"answer":0,"explain":"Sant Kirpal Singh Ji Maharaj lived from 1894 to 1974.","source":"sos.org/sant-rajinder-singh-ji-maharaj"},{"q":"What are the years of Sant Darshan Singh Ji Maharaj?","options":["1894–1974","1921–1989","1946–present","1900–1950"],"answer":1,"explain":"Sant Darshan Singh Ji Maharaj lived from 1921 to 1989.","source":"sos.org/sant-rajinder-singh-ji-maharaj"},{"q":"Who is the present spiritual head of Science of Spirituality?","options":["Sant Rajinder Singh Ji Maharaj","Sant Kirpal Singh Ji Maharaj","Sant Darshan Singh Ji Maharaj","There is none"],"answer":0,"explain":"Sant Rajinder Singh Ji Maharaj has been the spiritual head since 1989.","source":"sos.org/about-us"},{"q":"What is Science of Spirituality called in India?","options":["Sawan Kirpal Ruhani Mission","Art of Living","Ramakrishna Mission","Isha Foundation"],"answer":0,"explain":"In India the organization is known as Sawan Kirpal Ruhani Mission (SKRM).","source":"sos.org/about-us"},{"q":"According to Sant Kirpal Singh Ji, what does ''Guru'' mean?","options":["One who takes us from darkness to light","A teacher of music","A wealthy person","An elder"],"answer":0,"explain":"''Gu'' means darkness and ''ru'' means light: one who takes us from darkness to light.","source":"sos.org/spirituality/spiritual-master"},{"q":"Sant Darshan Singh Ji Maharaj was widely known as a…","options":["Poet-saint who wrote in Urdu","Professional athlete","Film director","Banker"],"answer":0,"explain":"He was recognised as one of India''s leading poet-saints, writing in Urdu.","source":"Wikipedia: Darshan Singh (spiritual master)"},{"q":"In which year did Sant Kirpal Singh Ji convene the first World Conference on Unity of Man?","options":["1947","1974","1989","2005"],"answer":1,"explain":"The first World Conference on Unity of Man was held in Delhi in February 1974.","source":"Biographical sketch of Sant Kirpal Singh Ji (please verify)"},{"q":"What is a spiritual Master, according to sos.org?","options":["One who has completed and mastered the spiritual course","Anyone who reads scriptures","A title bought with money","A famous speaker"],"answer":0,"explain":"A spiritual Master has completed and mastered the spiritual course and teaches from personal experience.","source":"sos.org/spirituality/spiritual-master"},{"q":"Does a spiritual Master guide in both worldly and spiritual matters?","options":["Yes","No"],"answer":0,"explain":"sos.org: the Master lays out a spiritual path and is an ongoing guide in worldly and spiritual matters.","source":"sos.org/spirituality/spiritual-master"},{"q":"Where is the international headquarters of Science of Spirituality?","options":["Lisle, Illinois (International Meditation Center)","Minneapolis, Minnesota","New York City","London"],"answer":0,"explain":"The international headquarters is the International Meditation Center in Lisle, Illinois.","source":"sos.org/about-us"}],"related":["know-the-masters"],"reviewNote":""}', 8, 10, 'draft', 70, strftime('%s','now') * 1000, strftime('%s','now') * 1000);
INSERT OR IGNORE INTO library (id, kind, title, author, summary, icon, topics, quiz, pass_mark, retry_minutes, status, priority, created_at, updated_at) VALUES ('q-ethical', 'quiz', 'Ethical Living and the Introspection Diary', 'Draft for review', 'The virtues that support meditation, and how the introspection diary helps us grow.', '🧩', 'ethics', '{"questions":[{"q":"Which of these is one of the virtues in Sant Kirpal Singh Ji''s ''Seven Paths to Perfection''?","options":["Non-violence","Competitiveness","Wealth","Fame"],"answer":0,"explain":"The seven paths: non-violence, truthfulness, chastity, loving humility, diet, selfless service and spiritual practices.","source":"Sant Kirpal Singh Ji, Seven Paths to Perfection"},{"q":"What is the introspection diary used for?","options":["Daily self-examination of our virtues and meditation","Recording expenses","Planning holidays","Writing stories"],"answer":0,"explain":"The self-introspection diary helps us check our thoughts, words and deeds against the virtues, and our meditation time.","source":"Sant Kirpal Singh Ji, Seven Paths to Perfection"},{"q":"Why does Science of Spirituality recommend a vegetarian diet?","options":["Out of non-violence and respect for all life","Because it is cheaper","For fashion","It doesn''t recommend one"],"answer":0,"explain":"The basis is not to take the life of, or harm, any living creature.","source":"sos.org/vegetarianism-and-spirituality"},{"q":"How is a vegetarian diet said to relate to meditation?","options":["It complements meditation by supporting calm and stillness","It makes meditation harder","It has no relation","It replaces meditation"],"answer":0,"explain":"Vegetarianism is described as complementing meditation, which needs calm and stillness.","source":"sos.org/vegetarianism-and-spirituality"},{"q":"Is truthfulness one of the virtues we aim to develop?","options":["Yes","No"],"answer":0,"explain":"Truthfulness is one of the seven paths.","source":"Sant Kirpal Singh Ji, Seven Paths to Perfection"},{"q":"What kind of humility is meant?","options":["Loving humility","False modesty","Weakness","Silence only"],"answer":0,"explain":"The virtue is ''loving humility''.","source":"Sant Kirpal Singh Ji, Seven Paths to Perfection"},{"q":"Which virtue is about helping others without expecting anything in return?","options":["Selfless service","Ambition","Thrift","Punctuality"],"answer":0,"explain":"Selfless service is one of the seven paths.","source":"Sant Kirpal Singh Ji, Seven Paths to Perfection"},{"q":"Why keep the diary every day rather than once a month?","options":["Daily review helps us notice and correct small faults early","It is required by law","It isn''t useful","To compare with others"],"answer":0,"explain":"Regular introspection helps us steadily weed out faults and grow in virtue.","source":"Teachings on introspection (please review)"},{"q":"Does ethical living support progress in meditation?","options":["Yes","No"],"answer":0,"explain":"A calm, ethical life helps the mind become still for meditation.","source":"Sant Kirpal Singh Ji, Seven Paths to Perfection; sos.org/vegetarianism-and-spirituality"},{"q":"Compassion in the teachings extends to…","options":["Animals, other people and ourselves","Only family","Only friends","Only humans"],"answer":0,"explain":"sos.org speaks of compassion for animals, other people and oneself.","source":"sos.org/vegetarianism-and-spirituality"}],"related":["spiritual-goals"],"reviewNote":"The list of virtues follows Sant Kirpal Singh Ji''s ''Seven Paths to Perfection''; please confirm the wording used at our center."}', 8, 10, 'draft', 80, strftime('%s','now') * 1000, strftime('%s','now') * 1000);
INSERT OR IGNORE INTO library (id, kind, title, author, summary, icon, topics, quiz, pass_mark, retry_minutes, status, priority, created_at, updated_at) VALUES ('q-seva', 'quiz', 'Seva: Selfless Service', 'Draft for review', 'What selfless service means and how it helps us and our community.', '🧩', 'seva', '{"questions":[{"q":"What does ''seva'' mean?","options":["Selfless service","A type of meal","A holiday","A prayer book"],"answer":0,"explain":"Seva is selfless service, offered without expecting anything in return.","source":"General meaning (please review)"},{"q":"According to sos.org, serving others is…","options":["A core tenet of Science of Spirituality","Optional and discouraged","Only for leaders","Paid work"],"answer":0,"explain":"sos.org describes serving others as a core tenet, shown through volunteer work, disaster relief, food programs and free health camps.","source":"sos.org/about-us"},{"q":"Who runs Science of Spirituality''s programs?","options":["Volunteers, with no one receiving a salary","Paid staff only","A company","The government"],"answer":0,"explain":"sos.org: volunteers run the organization and no one receives a salary.","source":"sos.org/about-us"},{"q":"What makes service ''selfless''?","options":["Doing it without expecting reward or recognition","Doing it only when noticed","Charging a small fee","Doing it for points"],"answer":0,"explain":"Selfless service is offered for its own sake, with no expectation of return.","source":"Teachings on selfless service (please review)"},{"q":"Which of these is an example of seva at our center?","options":["Greeting visitors and helping set up","Selling tickets","Advertising products","Charging for parking"],"answer":0,"explain":"Greeting, setup, kitchen, youth programs, tech and outreach are examples of center seva.","source":"Minneapolis center (please review)"},{"q":"Can seva include serving the wider community, not only the center?","options":["Yes","No"],"answer":0,"explain":"SOS volunteers serve through disaster relief, food programs and health camps.","source":"sos.org/about-us"},{"q":"How does selfless service help us spiritually?","options":["It helps reduce ego and grow love and compassion","It makes us proud","It has no effect","It replaces meditation"],"answer":0,"explain":"Service with the right attitude softens the ego and expands love.","source":"Teachings on selfless service (please review)"},{"q":"Is selfless service one of Sant Kirpal Singh Ji''s seven paths?","options":["Yes","No"],"answer":0,"explain":"Selfless service is one of the seven paths to perfection.","source":"Sant Kirpal Singh Ji, Seven Paths to Perfection"},{"q":"Which festival, inspired by Sant Rajinder Singh Ji, relies heavily on volunteers?","options":["Veggie Fest","Super Bowl","State Fair","Film festival"],"answer":0,"explain":"Veggie Fest, inspired by Sant Rajinder Singh Ji, is run with the help of many volunteers.","source":"sos.org/sant-rajinder-singh-ji-maharaj"},{"q":"Does seva replace daily meditation?","options":["Yes","No"],"answer":1,"explain":"Seva and meditation go together; one doesn''t replace the other.","source":"Sant Kirpal Singh Ji, Seven Paths to Perfection (spiritual practices)"}],"related":[],"reviewNote":"Please confirm the center-specific examples."}', 8, 10, 'draft', 90, strftime('%s','now') * 1000, strftime('%s','now') * 1000);
INSERT OR IGNORE INTO library (id, kind, title, author, summary, icon, topics, quiz, pass_mark, retry_minutes, status, priority, created_at, updated_at) VALUES ('q-stress', 'quiz', 'Meditation for Stress, Health and Peace', 'Draft for review', 'How meditation helps with stress, health and inner and outer peace.', '🧩', 'health,peace', '{"questions":[{"q":"Which stress-related conditions does sos.org say regular meditation can ease?","options":["High blood pressure, insomnia, chronic pain and fatigue","Broken bones","Colds only","None"],"answer":0,"explain":"sos.org lists high blood pressure, insomnia, chronic pain and fatigue.","source":"sos.org/benefits-from-meditation"},{"q":"What do many medical centers and hospitals now offer?","options":["Meditation classes","Nothing related","Only medicines","Meditation is banned"],"answer":0,"explain":"sos.org notes that many medical centers and hospitals now offer meditation classes.","source":"sos.org/benefits-from-meditation"},{"q":"How can meditation help us face conflict?","options":["We respond more calmly and control our reactions","We become more reactive","We avoid all people","It has no effect"],"answer":0,"explain":"Practitioners are described as better able to handle conflict and adversity calmly.","source":"sos.org/benefits-from-meditation"},{"q":"Should you stop prescribed medical treatment because you meditate?","options":["Yes","No"],"answer":1,"explain":"No. Meditation complements care; please talk with a health professional about any health concern.","source":"Copilot Learn: Benefits of Meditation"},{"q":"Which book by Sant Rajinder Singh Ji focuses on removing mental toxins that cause stress?","options":["Detox the Mind","Atomic Habits","The Secret","Deep Work"],"answer":0,"explain":"Detox the Mind is one of his books; SOS also runs ''Detox the Mind'' webinars on stress.","source":"sos.org/sant-rajinder-singh-ji-maharaj; SOS webinar listings"},{"q":"Which book title links inner peace to world peace?","options":["Inner and Outer Peace through Meditation","War and Peace","Peace Is Every Step","A New Earth"],"answer":0,"explain":"Inner and Outer Peace through Meditation is by Sant Rajinder Singh Ji Maharaj.","source":"sos.org/sant-rajinder-singh-ji-maharaj"},{"q":"How does meditation change our perspective on small worries?","options":["Minor concerns matter less","Everything seems bigger","Nothing changes","We worry more"],"answer":0,"explain":"Meditation is said to shift our outlook so that minor concerns matter less.","source":"sos.org/benefits-from-meditation"},{"q":"What helps stress relief from meditation the most?","options":["Sitting regularly every day","Meditating once a year","Reading about it only","Meditating only when very upset"],"answer":0,"explain":"Regular, accurate daily time brings lasting benefits.","source":"sos.org/benefits-from-meditation"},{"q":"Can meditation help people feel less lonely or insecure?","options":["Yes","No"],"answer":0,"explain":"sos.org presents meditation as a supplement that can help people feel less lonely, unfulfilled or insecure.","source":"sos.org/benefits-from-meditation"},{"q":"A 2017 study reported by ScienceDaily suggested meditation and yoga may…","options":["Reverse DNA reactions that cause stress","Change eye colour","Replace exercise","Increase stress"],"answer":0,"explain":"sos.org cites a 2017 ScienceDaily report suggesting meditation and yoga may ''reverse'' DNA reactions that cause stress.","source":"sos.org/benefits-from-meditation"}],"related":["benefits"],"reviewNote":""}', 8, 10, 'draft', 100, strftime('%s','now') * 1000, strftime('%s','now') * 1000);
INSERT OR IGNORE INTO library (id, kind, title, author, summary, icon, topics, quiz, pass_mark, retry_minutes, status, priority, created_at, updated_at) VALUES ('q-center', 'quiz', 'Your Meditation Center', 'Draft for review', 'Getting to know the Minneapolis Meditation Center and its programs.', '🧩', 'satsang', '{"questions":[{"q":"How much do programs at the center cost?","options":["Nothing: all programs are free","$10 per visit","A yearly membership","Donations are required"],"answer":0,"explain":"All programs are free of charge and open to everyone.","source":"sosmn.org"},{"q":"Who runs the center?","options":["Volunteers","A company","The city","Paid staff"],"answer":0,"explain":"The center is run by volunteers.","source":"sosmn.org; sos.org/about-us"},{"q":"In which city is the Minneapolis Meditation Center located?","options":["Columbia Heights","St. Cloud","Duluth","Rochester"],"answer":0,"explain":"4054 Van Buren St NE, Columbia Heights, MN.","source":"sosmn.org/about"},{"q":"Is photography allowed on the premises without permission?","options":["Yes","No"],"answer":1,"explain":"Please ask a volunteer before taking photos or video.","source":"sosmn.org/guidelines"},{"q":"How do you check in when you arrive?","options":["Scan the QR code at the welcome table","Pay at the door","Call ahead","No check-in"],"answer":0,"explain":"Scan the QR code at the welcome table, or check in on the event page.","source":"sosmn.org/guidelines"},{"q":"What should you do with your phone during meditation?","options":["Set it to silent","Keep the ringer on","Make calls quietly","Play music"],"answer":0,"explain":"Please set your phone to silent during meditation.","source":"sosmn.org/guidelines"},{"q":"If an event has no children''s program, what should parents do?","options":["Keep children with them","Leave children outside","Skip the event","Ask children to meditate alone"],"answer":0,"explain":"Children are welcome; without a children''s program, please keep them with you.","source":"sosmn.org/guidelines"},{"q":"Where can you find upcoming events?","options":["sosmn.org Events and Calendar","The newspaper only","Nowhere","By guessing"],"answer":0,"explain":"Upcoming events are on sosmn.org (Events and Calendar).","source":"sosmn.org"},{"q":"Can you contact the center by email?","options":["Yes, MinneapolisCenter@sos.org","No"],"answer":0,"explain":"Email MinneapolisCenter@sos.org with any questions.","source":"sosmn.org"},{"q":"Is the center monitored by video for safety and security?","options":["Yes","No"],"answer":0,"explain":"For safety and security, the premises are monitored by video.","source":"sosmn.org/guidelines"}],"related":["find-center"],"reviewNote":""}', 8, 10, 'draft', 110, strftime('%s','now') * 1000, strftime('%s','now') * 1000);
